:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #172b2a;
  color: #f7f3e9;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 0%, #31524a 0, #203b36 40%, #172b2a 78%);
}

button { font: inherit; }

.board {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 48px);
  text-align: center;
  background: #203b36;
  border: 2px solid #527363;
  border-radius: 22px;
  box-shadow: 0 18px 60px #0c1918aa, inset 0 1px #ffffff12;
}

.heading { margin-bottom: 28px; }
.eyebrow { margin: 0 0 8px; color: #a9c6ad; font-size: .85rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.6rem); line-height: 1.15; letter-spacing: -.04em; }
.hint { margin: 12px 0 0; color: #c9d9ca; }

.clocks { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.clock {
  min-width: 0;
  min-height: 204px;
  padding: 20px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  border: 3px solid transparent;
  border-radius: 16px;
  cursor: pointer;
  transition: transform .14s ease, border-color .14s ease, filter .14s ease;
}
.clock-light { color: #203b36; background: #f1e9d7; }
.clock-dark { color: #f7f3e9; background: #31524a; border-color: #527363; }
.clock:hover:not(:disabled) { transform: translateY(-3px); filter: brightness(1.08); }
.clock:active:not(:disabled) { transform: translateY(1px) scale(.99); }
.clock:focus-visible, .pause-button:focus-visible { outline: 3px solid #e7bd60; outline-offset: 4px; }
.clock.active { border-color: #e7bd60; box-shadow: 0 0 0 3px #e7bd6033; }
.clock:disabled { cursor: default; opacity: .75; }
.player { font-size: 1.1rem; font-weight: 750; }
.piece { margin-right: 5px; font-size: 1.25rem; }
.time { font-variant-numeric: tabular-nums; font-size: clamp(2.7rem, 10vw, 4.3rem); line-height: 1; font-weight: 800; letter-spacing: -.055em; }
.turn { min-height: 1.3em; font-size: .9rem; font-weight: 700; }

.status { min-height: 1.6em; margin: 24px 0 16px; color: #e7bd60; font-size: 1.15rem; font-weight: 750; }
.pause-button {
  min-width: 150px;
  padding: 12px 20px;
  color: #203b36;
  background: #e7bd60;
  border: 0;
  border-radius: 10px;
  font-weight: 750;
  cursor: pointer;
  transition: background .14s ease, transform .14s ease;
}
.pause-button:hover:not(:disabled) { background: #f2d58d; }
.pause-button:active:not(:disabled) { transform: scale(.97); }
.pause-button:disabled { cursor: default; opacity: .55; }
.pause-button span { margin-left: 6px; }
.footer { margin: 24px 0 0; color: #a9c6ad; font-size: .9rem; }
.footer span { padding: 0 5px; color: #e7bd60; }

@media (max-width: 430px) {
  .board { padding: 24px 16px; }
  .clocks { gap: 10px; }
  .clock { min-height: 178px; padding: 16px 8px; gap: 12px; }
  .player { font-size: 1rem; }
}

(() => {
  const START_TIME = 5 * 60;
  const players = {
    white: {
      button: document.getElementById("white-clock"),
      display: document.getElementById("white-time"),
      turn: document.getElementById("white-turn"),
      label: "White",
      remaining: START_TIME
    },
    black: {
      button: document.getElementById("black-clock"),
      display: document.getElementById("black-time"),
      turn: document.getElementById("black-turn"),
      label: "Black",
      remaining: START_TIME
    }
  };
  const status = document.getElementById("status");
  const pauseButton = document.getElementById("pause-button");
  let active = "white";
  let running = true;
  let flagged = false;
  let lastTick = performance.now();
  let timerId;

  function formatTime(seconds) {
    const wholeSeconds = Math.max(0, Math.ceil(seconds));
    const minutes = Math.floor(wholeSeconds / 60);
    const remainder = String(wholeSeconds % 60).padStart(2, "0");
    return `${minutes}:${remainder}`;
  }

  function render() {
    for (const [key, player] of Object.entries(players)) {
      player.display.textContent = formatTime(player.remaining);
      player.button.classList.toggle("active", key === active && running && !flagged);
      player.button.setAttribute("aria-pressed", String(key === active && running && !flagged));
      player.button.setAttribute("aria-label", `${player.label} clock, ${formatTime(player.remaining)} remaining. ${flagged || !running ? "Clock stopped." : key === active ? "Tap to end this turn." : "Waiting for this turn."}`);
      player.turn.textContent = flagged && key === active ? "Flag!" : key === active && running ? "Your move" : key === active ? "Paused" : "Waiting";
      player.button.disabled = flagged || !running || key !== active;
    }
    pauseButton.disabled = flagged;
    pauseButton.innerHTML = running ? 'Ⅱ <span>Pause</span>' : '▶ <span>Resume</span>';
    pauseButton.setAttribute("aria-label", running ? "Pause clocks" : "Resume clocks");
  }

  function tick() {
    const now = performance.now();
    if (running && !flagged) {
      players[active].remaining -= (now - lastTick) / 1000;
      if (players[active].remaining <= 0) {
        players[active].remaining = 0;
        running = false;
        flagged = true;
        status.textContent = `${players[active].label} Flag!`;
      }
      render();
    }
    lastTick = now;
  }

  for (const [key, player] of Object.entries(players)) {
    player.button.addEventListener("click", () => {
      if (!running || flagged || key !== active) return;
      tick();
      if (flagged) return;
      active = key === "white" ? "black" : "white";
      lastTick = performance.now();
      status.textContent = `${players[active].label} to move`;
      render();
    });
  }

  pauseButton.addEventListener("click", () => {
    if (flagged) return;
    if (running) tick();
    if (flagged) return;
    running = !running;
    lastTick = performance.now();
    status.textContent = running ? `${players[active].label} to move` : "Paused";
    render();
  });

  render();
  timerId = window.setInterval(tick, 100);
  window.addEventListener("pagehide", () => window.clearInterval(timerId), { once: true });
})();
